package com.retro.launcher;
import android.os.*;
final class PointerSupport {
 private PointerSupport(){}
 private static IBinder service;private static volatile boolean shown;private static Binder listener;
 private static IBinder connect()throws Exception{if(service!=null&&service.isBinderAlive())return service;IBinder found=(IBinder)Class.forName("android.os.ServiceManager").getMethod("getService",String.class).invoke(null,"kcpointer");if(found==null||!"com.kyocera.pointer.IKcPointerManager".equals(found.getInterfaceDescriptor()))throw new IllegalStateException("Cursor service unavailable");service=found;listener=new Binder(){protected boolean onTransact(int code,Parcel data,Parcel reply,int flags)throws RemoteException{if(code==INTERFACE_TRANSACTION){if(reply!=null)reply.writeString("com.kyocera.pointer.IKcPointerStateLstn");return true;}if(code==FIRST_CALL_TRANSACTION){data.enforceInterface("com.kyocera.pointer.IKcPointerStateLstn");shown=data.readInt()!=0;if(reply!=null)reply.writeNoException();return true;}return super.onTransact(code,data,reply,flags);}};Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken("com.kyocera.pointer.IKcPointerManager");data.writeStrongBinder(listener);if(!service.transact(4,data,reply,0))throw new IllegalStateException("Cursor listener unsupported");reply.readException();}finally{data.recycle();reply.recycle();}return service;}
 static void toggle(MainActivity activity){try{IBinder target=connect();Parcel data=Parcel.obtain(),reply=Parcel.obtain();try{data.writeInterfaceToken("com.kyocera.pointer.IKcPointerManager");data.writeInt(shown?0:1);if(!target.transact(3,data,reply,0))throw new IllegalStateException("Cursor toggle unsupported");reply.readException();}finally{data.recycle();reply.recycle();}}catch(Exception e){android.util.Log.w("OrbitCursor","Native cursor request failed",e);service=null;activity.features.toast("Cursor request failed on this firmware");}}
}
